// Fabricates a v5-shaped unified command so the bridge chain can be tested
// WITHOUT the v5 flow or hardware. Alternates Happy <-> DryAir on every press,
// so each press is a genuine state transition with a unique eventId.
const previous = flow.get("bridgeTestState") || "Happy";
const next = previous === "Happy" ? "DryAir" : "Happy";
flow.set("bridgeTestState", next);

msg.payload = {
    type: "plantCommand",
    plant: "BridgeTest",
    timestamp: Date.now(),
    readings: {
        temperature: 26.5,
        humidity: next === "DryAir" ? 32 : 55,
        light: 1,
        soilPH: 6.5
    },
    status: {
        primaryState: next,
        soilStatus: "Optimal",
        healthy: next === "Happy",
        warnings: next === "DryAir"
            ? ["Air humidity is low; check soil moisture before watering"]
            : [],
        stateChanged: true,
        previousPrimaryState: previous
    },
    game: { totalXP: 0, level: 1 },
    output: {}
};
return msg;

// PHASE 18 BRIDGE - taps the v5 unified device command.
// Wire the single output (port 1) of the v5 function node
// "Build Unified Device Command" (tab "LeafTalk Core Flow v5 · DB Persistence")
// into this node as an ADDITIONAL parallel wire. Expected msg.payload:
//   { type:"plantCommand", timestamp, readings:{temperature,humidity,light,soilPH},
//     status:{stateChanged, previousPrimaryState, primaryState, ...}, game, output }
// Emits a PLANT_STATE_CHANGED device event ONLY when status.stateChanged is
// true; returns null otherwise so nothing reaches the game API in between.

const cmd = msg.payload;

if (!cmd || cmd.type !== "plantCommand" || !cmd.status || !cmd.readings) {
    node.warn("Build Game Event: expected the v5 unified plantCommand payload - check the wiring (tap 'Build Unified Device Command').");
    return null;
}

if (cmd.status.stateChanged !== true) {
    return null;
}

// v5 primaryState codes ("Happy","Overheating","DryAir","Sleepy","SoilAcidic",
// "SoilAlkaline" - see v5 "Combine Plant State") match PLANT_MOODS in
// src/types/events.ts exactly. Normalize defensively with the same rule as the
// API's normalizeMood() so a future label tweak ("Dry Air") cannot break us.
const PLANT_MOODS = ["Happy", "Overheating", "DryAir", "Sleepy", "SoilAcidic", "SoilAlkaline"];
function normalizeMood(value) {
    if (typeof value !== "string") return null;
    const compact = value.replace(/[\s_-]/g, "").toLowerCase();
    for (const mood of PLANT_MOODS) {
        if (mood.toLowerCase() === compact) return mood;
    }
    return null;
}

const currentState = normalizeMood(cmd.status.primaryState);
if (!currentState) {
    node.warn("Build Game Event: unknown primaryState '" + cmd.status.primaryState + "' - event skipped.");
    return null;
}

// previousPrimaryState is null on the first command after a Node-RED restart
// or runtime reset - the game API accepts a null/omitted previousState.
const previousState = normalizeMood(cmd.status.previousPrimaryState);

// v5 sets timestamp = Date.now() (epoch ms) in "Validate & Normalize Sensor Data".
const ts = Number(cmd.timestamp);
if (!Number.isFinite(ts)) {
    node.warn("Build Game Event: command has no numeric timestamp - event skipped.");
    return null;
}

const readings = cmd.readings;

msg.payload = {
    eventId: "evt-plant-01-" + ts + "-" + currentState.toLowerCase(),
    plantId: "plant-01",
    type: "PLANT_STATE_CHANGED",
    occurredAt: new Date(ts).toISOString(),
    data: {
        previousState: previousState,
        currentState: currentState,
        temperature: readings.temperature,
        humidity: readings.humidity,
        light: readings.light,
        soilPH: readings.soilPH
    }
};

msg.headers = { "Content-Type": "application/json" };
const token = env.get("DEVICE_API_TOKEN");
if (token) {
    msg.headers.Authorization = "Bearer " + token;
}

// Drop v5 internals so the outgoing HTTP message stays small and clean.
delete msg.profile;
delete msg.plantState;
delete msg.game;
delete msg.device;
delete msg.event;
delete msg.analysis;
delete msg.stateChanged;
delete msg.previousPrimaryState;
delete msg.topic;

return msg;

// Fabricates a v5-shaped watchdog systemEvent so the sensor-status chain can
// be tested WITHOUT the v5 flow or hardware. Alternates
// sensorOffline <-> sensorRecovered on every press, so each press is a
// genuine connectivity transition with a unique eventId.
const previous = flow.get("bridgeTestSensorState") || "sensorRecovered";
const next = previous === "sensorRecovered" ? "sensorOffline" : "sensorRecovered";
flow.set("bridgeTestSensorState", next);

msg.payload = {
    type: "systemEvent",
    event: { type: next, timestamp: Date.now() }
};
if (next === "sensorOffline") {
    // fn_watch attaches a local device output on the offline edge; mirror it
    // so the test message has the exact v5 shape.
    msg.payload.output = {
        lcd: { line1: "Sensor offline", line2: "Check connection" },
        ledColor: "red",
        buzzer: true,
        servoAction: "hold"
    };
}
return msg;

// PHASE 18 BRIDGE - taps the v5 sensor watchdog.
// Wire the single output (port 1) of the v5 function node "Sensor Watchdog"
// (id: fn_watch, tab "LeafTalk Core Flow v5 · DB Persistence") into this node
// as an ADDITIONAL parallel wire. That port currently feeds only the
// "System Event Preview" debug node - this becomes the 2nd parallel branch.
// Expected msg.payload (built by fn_watch):
//   { type:"systemEvent",
//     event:{ type:"sensorOffline"|"sensorRecovered", timestamp }, output? }
//
// fn_watch already emits ONLY on transitions (it tracks flow.sensorOffline
// and returns null on repeated 10s ticks). But v5 "RESET · Runtime State"
// clears that flag, so a still-dead sensor would produce a SECOND
// sensorOffline with no sensorRecovered in between. This node therefore
// tracks the last status it forwarded (bridge-owned flow key
// "bridgeLastSensorStatus" - never touches v5 keys) and forwards
// TRANSITIONS ONLY. The API also dedups by eventId, but we do not rely on it.

const cmd = msg.payload;

if (!cmd || cmd.type !== "systemEvent" || !cmd.event || typeof cmd.event.type !== "string") {
    node.warn("Build Sensor Status Event: expected the v5 watchdog systemEvent payload - check the wiring (tap 'Sensor Watchdog').");
    return null;
}

let status = null;
if (cmd.event.type === "sensorOffline") status = "offline";
else if (cmd.event.type === "sensorRecovered") status = "online";
if (status === null) {
    // Some other/future systemEvent type - not a connectivity transition.
    return null;
}

// fn_watch sets event.timestamp = Date.now() (epoch ms).
const ts = Number(cmd.event.timestamp);
if (!Number.isFinite(ts)) {
    node.warn("Build Sensor Status Event: watchdog event has no numeric timestamp - event skipped.");
    return null;
}

// Transition-only gate (see header comment). Checked AFTER validation so a
// malformed message can never consume a real transition.
const last = flow.get("bridgeLastSensorStatus");
if (last === status) {
    return null;
}
flow.set("bridgeLastSensorStatus", status);

msg.payload = {
    eventId: "evt-plant-01-" + ts + "-sensor-" + status,
    plantId: "plant-01",
    type: status === "offline" ? "SENSOR_OFFLINE" : "SENSOR_ONLINE",
    occurredAt: new Date(ts).toISOString(),
    data: {}
};

msg.headers = { "Content-Type": "application/json" };
const token = env.get("DEVICE_API_TOKEN");
if (token) {
    msg.headers.Authorization = "Bearer " + token;
}

// Keep the outgoing HTTP message clean.
delete msg.topic;

return msg;
